// Hand-written `telegraf` stub for the flowatlas fixture suite.
//
// The receiver's type is the only signal that separates a bot from any other
// object with a method called `on`, so the adapter needs the class to resolve
// to this package. Only the shapes it matches on are declared, and the
// context a handler is handed, so its calls are the package's.

export type Trigger = string | RegExp;

export interface Context {
  callbackQuery?: { data?: string };
  message?: { text?: string };
  reply(text: string, extra?: unknown): Promise<void>;
  answerCbQuery(text?: string): Promise<void>;
}

export interface InlineButton {
  text: string;
  callback_data: string;
}

export declare const Markup: {
  button: { callback(text: string, data: string): InlineButton };
  inlineKeyboard(rows: InlineButton[][]): { reply_markup: unknown };
};

export declare class Telegraf {
  start(handler: (ctx: Context) => unknown): void;
  help(handler: (ctx: Context) => unknown): void;
  settings(handler: (ctx: Context) => unknown): void;
  command(trigger: Trigger | Trigger[], handler: (ctx: Context) => unknown): void;
  hears(trigger: Trigger | Trigger[], handler: (ctx: Context) => unknown): void;
  action(trigger: Trigger | Trigger[], handler: (ctx: Context) => unknown): void;
  on(update: string, handler: (ctx: Context) => unknown): void;
  launch(): void;
}
